"""
    Get all publications to an OAIPMH repository for an event.

    :param event: The event
    :type event: dict
    :return: OAIPMH publications
    :rtype: list
    """
def get_oaipmh_publications(event: Any) -> object {
    return [
        (publication["id"], publication["url"])
        for publication in event["publications"]
        if ("oaipmh" in publication["id"])
    ];
}

test_blocks:
test "t0" {
    assert (
        get_oaipmh_publications(
            {
                'publications': [
                    {'id': 'oai:example.org:1', 'url': 'https://example.org/oaipmh'},
                    {'id': 'oaipmh:1', 'url': 'https://oaipmh.example.org'}
                ]
            }
        )
        == [('oaipmh:1', 'https://oaipmh.example.org')]
    );;
}

