                        "url": "https://oaipmh.com/d"
                    },
                    {
                        "id": "oaipmh://publications.com/e",
                        "url": "https://oaipmh.com/e"
                    },
                    {"id": "oaipmh://publications.com/f", "url": "https://oaipmh.com/f"}
